mapper.select:
SELECT id, ds_id, db_type, biz_action, normalized_sql, sql_fingerprint, involved_tables, sample_questions, freq, accuracy, knowledge_source, confidence, verified, evidence, status, version, hit_count, error_count, create_time, update_time FROM kb_sql_template WHERE ds_id = #{dsId} AND verified = 1 AND status = 'active'
AND biz_action LIKE CONCAT(#{bizAction}, '%')
AND (sample_questions LIKE CONCAT('%', #{questionKeyword}, '%') OR normalized_sql LIKE CONCAT('%', #{questionKeyword}, '%') OR biz_action LIKE CONCAT('%', #{questionKeyword}, '%'))
AND involved_tables LIKE CONCAT('%', '"', #{tableName}, '"', '%')
AND confidence >= #{minConfidence}
ORDER BY confidence DESC, freq DESC, create_time DESC LIMIT #{topK}
